import{_ as e}from"./chunks/more.BA9dr6o4.js";import{_ as t,c as r,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"更多比較方式","description":"比較圖片與壓縮檔、把差異匯出成圖片，以及調整外觀與語言。","frontmatter":{"title":"更多比較方式","description":"比較圖片與壓縮檔、把差異匯出成圖片，以及調整外觀與語言。"},"headers":[],"relativePath":"zh-TW/guide/more.md","filePath":"zh-TW/guide/more.md","lastUpdated":1793948370000}'),l={name:"zh-TW/guide/more.md"};function s(n,a,h,d,p,c){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="更多比較方式" tabindex="-1">更多比較方式 <a class="header-anchor" href="#更多比較方式" aria-label="Permalink to &quot;更多比較方式&quot;">​</a></h1><p>文字只是其中一半。qDiff 用同樣的「並排」思路，也能打開別的內容。</p><img src="'+e+'" alt="兩張圖片並排比較" class="guide-shot"><h2 id="圖片" tabindex="-1">圖片 <a class="header-anchor" href="#圖片" aria-label="Permalink to &quot;圖片&quot;">​</a></h2><p>把兩張圖並排放著慢慢看，或者疊在一起，直接看出哪裡不一樣 —— 設計改版、 幾乎一模一樣的照片，都很合適。</p><h2 id="壓縮檔" tabindex="-1">壓縮檔 <a class="header-anchor" href="#壓縮檔" aria-label="Permalink to &quot;壓縮檔&quot;">​</a></h2><p>.zip / .tar 可以直接打開，像資料夾一樣比。不用解壓，也不用事後清理暫存檔。</p><h2 id="不是純文字的檔案" tabindex="-1">不是純文字的檔案 <a class="header-anchor" href="#不是純文字的檔案" aria-label="Permalink to &quot;不是純文字的檔案&quot;">​</a></h2><p>兩個檔案看起來一樣、用起來卻不同時，qDiff 還能細到最小的差別，把普通文字 視圖看不出來的變化也找出來。</p><h2 id="把一次比較存成圖片" tabindex="-1">把一次比較存成圖片 <a class="header-anchor" href="#把一次比較存成圖片" aria-label="Permalink to &quot;把一次比較存成圖片&quot;">​</a></h2><p>選中一處改動，匯出成一張乾淨的雙欄圖片，直接貼進聊天、文件或審查裡。 匯出的圖片不會加任何標記。</p><h2 id="按你的習慣來" tabindex="-1">按你的習慣來 <a class="header-anchor" href="#按你的習慣來" aria-label="Permalink to &quot;按你的習慣來&quot;">​</a></h2><ul><li><strong>外觀</strong> —— 淺色與深色，可以跟隨 Mac，也可以自己指定。</li><li><strong>語言</strong> —— 繁體中文、簡體中文、英文等多種介面語言。</li><li><strong>字體與快捷鍵</strong> —— 讀著舒服，常用的操作也能用鍵盤完成。</li><li><strong>最近比較</strong> —— 昨天看過的內容，在歡迎頁一點就回來。</li></ul><p>以上全部包含在免費版裡。</p><p>還有疑問？<a href="./faq.html">看看常見問題</a>。</p>',15)])])}const f=t(l,[["render",s]]);export{u as __pageData,f as default};
